+ */
+
+#include "config.h"
+
+#include <epan/packet.h>
+
+#include "packet-st291-vanc.h"
+
+static int proto_op47;
+
+static int hf_sdp_identifier;
+static int hf_sdp_length;
+static int hf_sdp_format_code;
+static int hf_sdp_adaption_header;
+static int hf_sdp_pkt_desc_b;
+static int hf_clock_runin;
+static int hf_framing_code;
+static int hf_magazine_hamming;
+static int hf_magazine;
+static int hf_packet_number_hamming;
+static int hf_packet_number;
+static int hf_page_units_hamming;
+static int hf_page_units;
+static int hf_page_tens_hamming;
+static int hf_page_tens;
+static int hf_data_string;
+static int hf_textdata_array;
+static int hf_erase_page;
+static int hf_newsflash;
+static int hf_subtitle;
+static int hf_suppress_header;
+static int hf_update_indicator;
+static int hf_interrupted_sequence;
+static int hf_inhibit_display;
+static int hf_magazine_serial;
+static int hf_character_set;
+static int hf_tt_control;
+
+static int ett_op47;
+static int ett_wst;
+
+static dissector_handle_t op47_handle;
+
+/* Rec. ITU-R BT.653-3, System B national-option character subsets used by OP-47 WST data. */
+static const value_string national_subset_vals[] = {
+    { 0x00, "English" },
+    { 0x01, "German" },
+    { 0x04, "Swedish/Finnish/Hungarian" },
+    { 0x05, "Italian" },
+    { 0x10, "French" },
+    { 0x11, "Portuguese/Spanish" },
+    { 0x14, "Czech/Slovak" },
+    { 0, NULL }
+};
+
+static uint32_t
+get_bits_buf(const uint8_t *buf, unsigned bit_off, unsigned nbits)
+{
+    uint32_t out = 0;
+    unsigned i;
+
+    for (i = 0; i < nbits; i++) {
+        unsigned absolute = bit_off + i;
+        unsigned bit_in_byte = absolute % 8;
+        out = (out << 1) | ((buf[absolute / 8] >> (7 - bit_in_byte)) & 1U);
+    }
+    return out;
+}
+
+static void
+add_generated_uint(proto_tree *tree, int hf, tvbuff_t *tvb, uint32_t value)
+{
+    proto_item *ti = proto_tree_add_uint(tree, hf, tvb, 0, 0, value);
+    proto_item_set_generated(ti);
+}
+
+/* OP-47 Issue 6, Sec. 5.5.2 carries a System B WST packet; magazine,
+ * packet number, page address, control bits and text follow Rec. ITU-R BT.653-3. */
+static void
+process_wst_packet(tvbuff_t *tvb, proto_tree *tree)
+{
+    uint8_t bytes[42];
+    uint8_t text_data[40];
+    char data_string[41];
+    unsigned magazine, packet_number;
+    unsigned data_start_offset = 0, number_of_data_bytes = 0;
+    proto_item *ti;
+    unsigned i;
+
+    if (tvb_captured_length(tvb) < 42)
+        return;
+
+    tvb_memcpy(tvb, bytes, 0, 42);
+
+    proto_tree_add_item(tree, hf_magazine_hamming, tvb, 0, 2, ENC_BIG_ENDIAN);
+    magazine = get_bits_buf(bytes, 1, 1)
+             + 2 * get_bits_buf(bytes, 3, 1)
+             + 4 * get_bits_buf(bytes, 5, 1);
+    if (magazine == 0)
+        magazine = 8;
+    add_generated_uint(tree, hf_magazine, tvb, magazine);
+
+    proto_tree_add_item(tree, hf_packet_number_hamming, tvb, 0, 2, ENC_BIG_ENDIAN);
+    packet_number = get_bits_buf(bytes, 7, 1)
+                  + 2 * get_bits_buf(bytes, 9, 1)
+                  + 4 * get_bits_buf(bytes, 11, 1)
+                  + 8 * get_bits_buf(bytes, 13, 1)
+                  + 16 * get_bits_buf(bytes, 15, 1);
+    add_generated_uint(tree, hf_packet_number, tvb, packet_number);
+
+    if (packet_number == 0) {
+        unsigned page_units, page_tens, tt_page;
+
+        data_start_offset = 10;
+        number_of_data_bytes = 32;
+        page_units = get_bits_buf(bytes + 2, 1, 1)
+                   + 2 * get_bits_buf(bytes + 2, 3, 1)
+                   + 4 * get_bits_buf(bytes + 2, 5, 1)
+                   + 8 * get_bits_buf(bytes + 2, 7, 1);
+        page_tens = get_bits_buf(bytes + 3, 1, 1)
+                  + 2 * get_bits_buf(bytes + 3, 3, 1)
+                  + 4 * get_bits_buf(bytes + 3, 5, 1)
+                  + 8 * get_bits_buf(bytes + 3, 7, 1);
+
+        proto_tree_add_item(tree, hf_page_units_hamming, tvb, 2, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_page_tens_hamming, tvb, 3, 1, ENC_BIG_ENDIAN);
+        add_generated_uint(tree, hf_page_units, tvb, page_units);
+        add_generated_uint(tree, hf_page_tens, tvb, page_tens);
+
+        tt_page = (magazine << 8) | (page_tens << 4) | page_units;
+        proto_tree_add_none_format(tree, hf_tt_control, tvb, 0, 0,
+                                   "Control bits for TT Page 0x%x:", tt_page);
+
+        proto_tree_add_item(tree, hf_erase_page, tvb, 5, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_newsflash, tvb, 7, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_subtitle, tvb, 7, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_suppress_header, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_update_indicator, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_interrupted_sequence, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_inhibit_display, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_magazine_serial, tvb, 9, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_character_set, tvb, 9, 1, ENC_BIG_ENDIAN);
+    } else if (packet_number >= 1 && packet_number <= 25) {
+        data_start_offset = 2;
+        number_of_data_bytes = 40;
+    }
+
+    if (number_of_data_bytes == 0)
+        return;
+
+    for (i = 0; i < number_of_data_bytes; i++) {
+        uint8_t c = (uint8_t)get_bits_buf(bytes + data_start_offset + i, 0, 7);
+        text_data[i] = c;
+        data_string[i] = (char)c;
+    }
+    data_string[number_of_data_bytes] = '\0';
+
+    ti = proto_tree_add_string(tree, hf_data_string, tvb, 0, 0, data_string);
+    proto_item_set_generated(ti);
+    ti = proto_tree_add_bytes(tree, hf_textdata_array, tvb, 0, 0, text_data);
+    proto_item_set_generated(ti);
+}
+
+static uint8_t
+reverse_byte(uint8_t v)
+{
+    v = (uint8_t)(((v & 0x55U) << 1) | ((v >> 1) & 0x55U));
+    v = (uint8_t)(((v & 0x33U) << 2) | ((v >> 2) & 0x33U));
+    v = (uint8_t)((v << 4) | (v >> 4));
+    return v;
+}
+
+/* Free TV Australia OP-47 Issue 6, Secs. 5.1, 5.4 and 5.5, Fig. 2. */
+static int
+dissect_op47(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data)
+{
+    const st291_vanc_dissector_data_t *st291_data = (const st291_vanc_dissector_data_t *)data;
+    proto_tree *top_tree = st291_data && st291_data->top_tree ? st291_data->top_tree : tree;
+    proto_item *ti;
+    proto_tree *op47_tree;
+    unsigned len = tvb_captured_length(tvb);
+    uint8_t format_code;
+    unsigned offset_a = 4, offset_b = 9, i;
+
+    if (len < 4)
+        return 0;
+
+    ti = proto_tree_add_item(top_tree, proto_op47, tvb, 0, -1, ENC_NA);
+    op47_tree = proto_item_add_subtree(ti, ett_op47);
+
+    /* OP-47 Issue 6, Sec. 5.1 and Fig. 2 -- SDP identifier, length and format code. */
+    proto_tree_add_item(op47_tree, hf_sdp_identifier, tvb, 0, 2, ENC_BIG_ENDIAN);
+    proto_tree_add_item(op47_tree, hf_sdp_length, tvb, 2, 1, ENC_BIG_ENDIAN);
+    proto_tree_add_item(op47_tree, hf_sdp_format_code, tvb, 3, 1, ENC_BIG_ENDIAN);
+    format_code = tvb_get_uint8(tvb, 3);
+    if (format_code != 0x02 || len < 9)
+        return len;
+
+    /* OP-47 Issue 6, Sec. 5.4 -- Packet Descriptor Structure A / adaptation header. */
+    ti = proto_tree_add_item(op47_tree, hf_sdp_adaption_header, tvb, 4, 5, ENC_NA);
+    proto_item_set_generated(ti);
+
+    for (i = 0; i < 5; i++) {
+        uint8_t pkt_desc_a;
+        uint8_t *flipped;
+        tvbuff_t *wst_tvb;
+        proto_tree *wst_tree;
+        unsigned j;
+
+        if (offset_a >= len)
+            break;
+        pkt_desc_a = tvb_get_uint8(tvb, offset_a);
+        if (pkt_desc_a == 0)
+            break;
+        if (offset_b + 45 > len)
+            break;
+
+        /* OP-47 Issue 6, Sec. 5.5 -- Packet Descriptor Structure B;
+         * Secs. 5.5.1-5.5.2 define clock run-in, framing code and WST data. */
+        ti = proto_tree_add_item(op47_tree, hf_sdp_pkt_desc_b, tvb, offset_b, 45, ENC_NA);
+        proto_item_set_generated(ti);
+        wst_tree = proto_item_add_subtree(ti, ett_wst);
+
+        ti = proto_tree_add_item(wst_tree, hf_clock_runin, tvb, offset_b, 2, ENC_BIG_ENDIAN);
+        proto_item_set_generated(ti);
+        ti = proto_tree_add_item(wst_tree, hf_framing_code, tvb, offset_b + 2, 1, ENC_BIG_ENDIAN);
+        proto_item_set_generated(ti);
+
+        flipped = wmem_alloc(pinfo->pool, 42);
+        for (j = 0; j < 42; j++)
+            flipped[j] = reverse_byte(tvb_get_uint8(tvb, offset_b + 3 + j));
+
+        wst_tvb = tvb_new_child_real_data(tvb, flipped, 42, 42);
+        add_new_data_source(pinfo, wst_tvb, "OP-47 WST data (bit reversed)");
+        process_wst_packet(wst_tvb, wst_tree);
+
+        offset_a++;
+        offset_b += 45;
+    }
+
+    return len;
+}
+
+void
+proto_register_op47(void)
+{
+    static hf_register_info hf[] = {
+        { &hf_sdp_identifier, { "Identifier", "op47.sdp.identifier", FT_UINT16, BASE_HEX, NULL, 0x0, NULL, HFILL } },
+        { &hf_sdp_length, { "Length", "op47.sdp.length", FT_UINT8, BASE_HEX, NULL, 0x0, NULL, HFILL } },
+        { &hf_sdp_format_code, { "Format Code", "op47.sdp.format_code", FT_UINT8, BASE_HEX, NULL, 0x0, NULL, HFILL } },
+        { &hf_sdp_adaption_header, { "Adaption Header", "op47.sdp.adaption_header", FT_BYTES, BASE_NONE, NULL, 0x0, NULL, HFILL } },
+        { &hf_sdp_pkt_desc_b, { "Packet Descriptor B", "op47.sdp.packet_descriptor_b", FT_BYTES, BASE_NONE, NULL, 0x0, NULL, HFILL } },
+        { &hf_clock_runin, { "Clock Run-In", "op47.wst.clock_runin", FT_UINT16, BASE_HEX, NULL, 0xFFFF, NULL, HFILL } },
+        { &hf_framing_code, { "Framing Code", "op47.wst.framing_code", FT_UINT8, BASE_HEX, NULL, 0xFF, NULL, HFILL } },
+        { &hf_magazine_hamming, { "Magazine (Hamming 8/4)", "op47.wst.magazine_hamming", FT_UINT16, BASE_DEC, NULL, 0xFC00, NULL, HFILL } },
+        { &hf_magazine, { "Magazine", "op47.wst.magazine", FT_UINT8, BASE_DEC, NULL, 0x0, NULL, HFILL } },
+        { &hf_packet_number_hamming, { "Packet Number (Hamming 8/4)", "op47.wst.packet_number_hamming", FT_UINT16, BASE_DEC, NULL, 0x03FF, NULL, HFILL } },
+        { &hf_packet_number, { "Packet Number", "op47.wst.packet_number", FT_UINT8, BASE_DEC, NULL, 0x0, NULL, HFILL } },
+        { &hf_page_units_hamming, { "Page Units (Hamming 8/4)", "op47.wst.page_units_hamming", FT_UINT8, BASE_HEX, NULL, 0xFF, NULL, HFILL } },
+        { &hf_page_units, { "Page Units", "op47.wst.page_units", FT_UINT8, BASE_HEX, NULL, 0x0, NULL, HFILL } },
+        { &hf_page_tens_hamming, { "Page Tens (Hamming 8/4)", "op47.wst.page_tens_hamming", FT_UINT8, BASE_HEX, NULL, 0xFF, NULL, HFILL } },
+        { &hf_page_tens, { "Page Tens", "op47.wst.page_tens", FT_UINT8, BASE_HEX, NULL, 0x0, NULL, HFILL } },
+        { &hf_data_string, { "Data String", "op47.wst.data_string", FT_STRING, BASE_NONE, NULL, 0x0, NULL, HFILL } },
+        { &hf_textdata_array, { "Text Data", "op47.wst.text_data", FT_BYTES, BASE_NONE, NULL, 0x0, NULL, HFILL } },
+        { &hf_erase_page, { "Erase Page", "op47.wst.erase_page", FT_BOOLEAN, 8, NULL, 0x01, NULL, HFILL } },
+        { &hf_newsflash, { "Newsflash", "op47.wst.newsflash", FT_BOOLEAN, 8, NULL, 0x04, NULL, HFILL } },
+        { &hf_subtitle, { "Subtitle", "op47.wst.subtitle", FT_BOOLEAN, 8, NULL, 0x01, NULL, HFILL } },
+        { &hf_suppress_header, { "Suppress Header", "op47.wst.suppress_header", FT_BOOLEAN, 8, NULL, 0x40, NULL, HFILL } },
+        { &hf_update_indicator, { "Update Indicator", "op47.wst.update_indicator", FT_BOOLEAN, 8, NULL, 0x10, NULL, HFILL } },
+        { &hf_interrupted_sequence, { "Interrupted Sequence", "op47.wst.interrupted_sequence", FT_BOOLEAN, 8, NULL, 0x04, NULL, HFILL } },
+        { &hf_inhibit_display, { "Inhibit Display", "op47.wst.inhibit_display", FT_BOOLEAN, 8, NULL, 0x01, NULL, HFILL } },
+        { &hf_magazine_serial, { "Magazine Serial", "op47.wst.magazine_serial", FT_BOOLEAN, 8, NULL, 0x40, NULL, HFILL } },
+        { &hf_character_set, { "Character Subset", "op47.wst.character_set", FT_UINT8, BASE_DEC, VALS(national_subset_vals), 0x15, NULL, HFILL } },
+        { &hf_tt_control, { "Teletext Control", "op47.wst.control", FT_NONE, BASE_NONE, NULL, 0x0, NULL, HFILL } },
+    };
+    static int *ett[] = {
+        &ett_op47,
+        &ett_wst,
+    };
+
+    proto_op47 = proto_register_protocol(
+        "RDD 8 / OP-47 Subtitle Distribution Packet", "OP-47", "op47");
+    proto_register_field_array(proto_op47, hf, array_length(hf));
+    proto_register_subtree_array(ett, array_length(ett));
+
+    op47_handle = register_dissector("op47", dissect_op47, proto_op47);
+}
+
+void
+proto_reg_handoff_op47(void)
+{
+    dissector_add_uint("st291.did_sdid", 0x4302, op47_handle);
+}
