+static int hf_binary_group_5;
+static int hf_binary_group_6;
+static int hf_binary_group_7;
+static int hf_binary_group_8;
+static int hf_flag_bit_10;
+static int hf_flag_bit_11;
+static int hf_flag_bit_27;
+static int hf_flag_bit_43;
+static int hf_flag_bit_58;
+static int hf_flag_bit_59;
