+    &ett_st2010_fragment,
+    &ett_st2010_fragments,
+    &hf_st2010_fragments,
+    &hf_st2010_fragment,
+    &hf_st2010_fragment_overlap,
+    &hf_st2010_fragment_overlap_conflict,
+    &hf_st2010_fragment_multiple_tails,
+    &hf_st2010_fragment_too_long_fragment,
+    &hf_st2010_fragment_error,
