+#include "config.h"
+
+#include <epan/expert.h>
+#include <epan/packet.h>
+#include <epan/tfs.h>
+
+#include <wsutil/array.h>
+
+#include "packet-st291-vanc.h"
+
+static int proto_st2016_3;
+
+static int hf_afd_byte;
+static int hf_afd_code;
+static int hf_afd_ar;
+static int hf_afd_reserved;
+static int hf_reserved_1;
+static int hf_reserved_2;
+static int hf_bar_flags;
+static int hf_bar_top;
+static int hf_bar_bottom;
+static int hf_bar_left;
+static int hf_bar_right;
+static int hf_bar_reserved;
+static int hf_bar_value_1;
+static int hf_bar_value_1_marker;
+static int hf_bar_value_1_data;
+static int hf_bar_value_2;
+static int hf_bar_value_2_marker;
+static int hf_bar_value_2_data;
+static int hf_bar_value_1_meaning;
+static int hf_bar_value_2_meaning;
+
+static int ett_st2016_3;
+static int ett_afd;
+static int ett_bar_flags;
+static int ett_bar_value_1;
+static int ett_bar_value_2;
+
+static expert_field ei_bad_length;
+static expert_field ei_afd_reserved;
+static expert_field ei_reserved_udw;
+static expert_field ei_bar_reserved;
+static expert_field ei_bar_flags_invalid;
+static expert_field ei_bar_marker;
+
+static dissector_handle_t st2016_3_handle;
+
+static const struct true_false_string tfs_afd_ar = {
+    "16:9 coded frame",
+    "4:3 coded frame"
+};
+
+/* SMPTE ST 2016-1:2009, Sec. 5, Table 1 -- AFD code meaning depends on coded-frame AR. */
+static const char *
+afd_description(uint8_t afd, bool ar_16_9)
+{
+    static const char *const afd_4_3[16] = {
+        "Undefined",
+        "Reserved",
+        "Letterbox 16:9 image, at top of coded frame",
+        "Letterbox 14:9 image, at top of coded frame",
+        "Letterbox image with aspect ratio greater than 16:9, vertically centered",
+        "Reserved",
+        "Reserved",
+        "Reserved",
+        "Full frame 4:3 image, same as coded frame",
+        "Full frame 4:3 image, same as coded frame",
+        "Letterbox 16:9 image, vertically centered, all image areas protected",
+        "Letterbox 14:9 image, vertically centered",
+        "Reserved",
+        "Full frame 4:3 image, with alternative 14:9 center",
+        "Letterbox 16:9 image, with alternative 14:9 center",
+        "Letterbox 16:9 image, with alternative 4:3 center"
+    };
+    static const char *const afd_16_9[16] = {
+        "Undefined",
+        "Reserved",
+        "Full frame 16:9 image, same as coded frame",
+        "Pillarbox 14:9 image, horizontally centered",
+        "Letterbox image with aspect ratio greater than 16:9, vertically centered",
+        "Reserved",
+        "Reserved",
+        "Reserved",
+        "Full frame 16:9 image, same as coded frame",
+        "Pillarbox 4:3 image, horizontally centered",
+        "Full frame 16:9 image, all image areas protected",
+        "Pillarbox 14:9 image, horizontally centered",
+        "Reserved",
+        "Pillarbox 4:3 image, with alternative 14:9 center",
+        "Full frame 16:9 image, with alternative 14:9 center",
+        "Full frame 16:9 image, with alternative 4:3 center"
+    };
+
+    return ar_16_9 ? afd_16_9[afd & 0x0f] : afd_4_3[afd & 0x0f];
+}
+
+/* SMPTE ST 2016-1:2009, Secs. 6, 9.2.1-9.2.2, Tables 3, 5 and 6. */
+static const char *
+bar_value_meaning(unsigned value_index, bool top, bool bottom, bool left, bool right)
+{
+    if (value_index == 1) {
+        if (top)
+            return "Line number: end of top bar";
+        if (bottom)
+            return "Line number: start of bottom bar";
+        if (left)
+            return "Pixel number: end of left bar";
+        if (right)
+            return "Pixel number: start of right bar";
+    } else {
+        if (top && bottom)
+            return "Line number: start of bottom bar";
+        if (left && right)
+            return "Pixel number: start of right bar";
+    }
+
+    return "No valid Bar Data value";
+}
+
+static int
+dissect_st2016_3(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data)
+{
+    const st291_vanc_dissector_data_t *st291_data =
+        (const st291_vanc_dissector_data_t *)data;
+    proto_tree *top_tree =
+        st291_data && st291_data->top_tree ? st291_data->top_tree : tree;
+    proto_item *ti;
+    proto_item *root_ti;
+    proto_tree *st2016_tree;
+    proto_tree *afd_tree;
+    proto_tree *flags_tree;
+    proto_tree *value_tree;
+    unsigned len = tvb_captured_length(tvb);
+    uint8_t afd_byte;
+    uint8_t afd;
+    bool ar_16_9;
+    uint8_t flags;
+    bool top;
+    bool bottom;
+    bool left;
+    bool right;
+    uint16_t value1;
+    uint16_t value2;
+    const char *meaning1;
+    const char *meaning2;
+
+    if (len == 0)
+        return 0;
+
+    root_ti = proto_tree_add_item(top_tree, proto_st2016_3, tvb, 0, len, ENC_NA);
+    st2016_tree = proto_item_add_subtree(root_ti, ett_st2016_3);
+
+    if (len != 8) {
+        expert_add_info_format(pinfo, root_ti, &ei_bad_length,
+                               "ST 2016-3 requires 8 UDW bytes; packet contains %u",
+                               len);
+    }
+
+    if (len < 1)
+        return len;
+
+    /* SMPTE ST 2016-3:2009, Sec. 4.1, Table 1 maps UDW1 to the
+     * ST 2016-1 AFD byte; ST 2016-1:2009, Sec. 9.1, Table 4 defines
+     * reserved bits, active_format and coded_frame_aspect_ratio. */
+    afd_byte = tvb_get_uint8(tvb, 0);
+    afd = (afd_byte >> 3) & 0x0f;
+    ar_16_9 = (afd_byte & 0x04) != 0;
+
+    ti = proto_tree_add_item(st2016_tree, hf_afd_byte, tvb, 0, 1, ENC_BIG_ENDIAN);
+    afd_tree = proto_item_add_subtree(ti, ett_afd);
+    proto_tree_add_item(afd_tree, hf_afd_reserved, tvb, 0, 1, ENC_BIG_ENDIAN);
+    proto_tree_add_uint_format_value(afd_tree, hf_afd_code, tvb, 0, 1, afd,
+                                     "%u (%s)", afd,
+                                     afd_description(afd, ar_16_9));
+    proto_tree_add_item(afd_tree, hf_afd_ar, tvb, 0, 1, ENC_BIG_ENDIAN);
+
+    if ((afd_byte & 0x83) != 0)
+        expert_add_info(pinfo, ti, &ei_afd_reserved);
+
+    if (len < 4)
+        return len;
+
+    /* SMPTE ST 2016-3:2009, Sec. 4.1, Table 1 -- UDW2 and UDW3 are reserved. */
+    ti = proto_tree_add_item(st2016_tree, hf_reserved_1, tvb, 1, 1, ENC_BIG_ENDIAN);
+    if (tvb_get_uint8(tvb, 1) != 0)
+        expert_add_info(pinfo, ti, &ei_reserved_udw);
+
+    ti = proto_tree_add_item(st2016_tree, hf_reserved_2, tvb, 2, 1, ENC_BIG_ENDIAN);
+    if (tvb_get_uint8(tvb, 2) != 0)
+        expert_add_info(pinfo, ti, &ei_reserved_udw);
+
+    /* SMPTE ST 2016-3:2009, Sec. 4.1, Table 1 maps UDW4 to Bar Data flags;
+     * SMPTE ST 2016-1:2009, Sec. 9.2.1, Table 5 defines top/bottom/left/right. */
+    flags = tvb_get_uint8(tvb, 3);
+    top = (flags & 0x80) != 0;
+    bottom = (flags & 0x40) != 0;
+    left = (flags & 0x20) != 0;
+    right = (flags & 0x10) != 0;
+
+    ti = proto_tree_add_item(st2016_tree, hf_bar_flags, tvb, 3, 1, ENC_BIG_ENDIAN);
+    flags_tree = proto_item_add_subtree(ti, ett_bar_flags);
+    proto_tree_add_item(flags_tree, hf_bar_top, tvb, 3, 1, ENC_BIG_ENDIAN);
+    proto_tree_add_item(flags_tree, hf_bar_bottom, tvb, 3, 1, ENC_BIG_ENDIAN);
+    proto_tree_add_item(flags_tree, hf_bar_left, tvb, 3, 1, ENC_BIG_ENDIAN);
+    proto_tree_add_item(flags_tree, hf_bar_right, tvb, 3, 1, ENC_BIG_ENDIAN);
+    proto_tree_add_item(flags_tree, hf_bar_reserved, tvb, 3, 1, ENC_BIG_ENDIAN);
+
+    if ((flags & 0x0f) != 0)
+        expert_add_info(pinfo, ti, &ei_bar_reserved);
+
+    if ((top != bottom) || (left != right) || ((top || bottom) && (left || right)))
+        expert_add_info(pinfo, ti, &ei_bar_flags_invalid);
+
+    if (len < 8)
+        return len;
+
+    /* SMPTE ST 2016-3:2009, Sec. 4.1, Table 1 maps UDW5-UDW8 to
+     * Bar Data Value 1/2; ST 2016-1:2009, Sec. 9.2.2, Table 6 defines
+     * marker bits and the 14-bit line/pixel values. */
+    value1 = tvb_get_ntohs(tvb, 4);
+    value2 = tvb_get_ntohs(tvb, 6);
+    meaning1 = bar_value_meaning(1, top, bottom, left, right);
+    meaning2 = bar_value_meaning(2, top, bottom, left, right);
+
+    ti = proto_tree_add_item(st2016_tree, hf_bar_value_1, tvb, 4, 2, ENC_BIG_ENDIAN);
+    value_tree = proto_item_add_subtree(ti, ett_bar_value_1);
+    proto_tree_add_item(value_tree, hf_bar_value_1_marker, tvb, 4, 2, ENC_BIG_ENDIAN);
+    proto_tree_add_item(value_tree, hf_bar_value_1_data, tvb, 4, 2, ENC_BIG_ENDIAN);
+    ti = proto_tree_add_string(value_tree, hf_bar_value_1_meaning, tvb, 4, 0,
+                               meaning1);
+    proto_item_set_generated(ti);
+
+    ti = proto_tree_add_item(st2016_tree, hf_bar_value_2, tvb, 6, 2, ENC_BIG_ENDIAN);
+    value_tree = proto_item_add_subtree(ti, ett_bar_value_2);
+    proto_tree_add_item(value_tree, hf_bar_value_2_marker, tvb, 6, 2, ENC_BIG_ENDIAN);
+    proto_tree_add_item(value_tree, hf_bar_value_2_data, tvb, 6, 2, ENC_BIG_ENDIAN);
+    ti = proto_tree_add_string(value_tree, hf_bar_value_2_meaning, tvb, 6, 0,
+                               meaning2);
+    proto_item_set_generated(ti);
+
+    if (top || bottom || left || right) {
+        if ((value1 & 0xc000) != 0xc000)
+            expert_add_info(pinfo, ti, &ei_bar_marker);
+        if ((top && bottom) || (left && right)) {
+            if ((value2 & 0xc000) != 0xc000)
+                expert_add_info(pinfo, ti, &ei_bar_marker);
+        }
+    }
+
+    proto_item_append_text(root_ti, ": AFD %u, %s", afd,
+                           ar_16_9 ? "16:9" : "4:3");
+
+    return len;
+}
+
+void
+proto_register_st2016_3(void)
+{
+    static hf_register_info hf[] = {
+        { &hf_afd_byte,
+          { "AFD Information", "st2016_3.afd", FT_UINT8, BASE_HEX,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_afd_code,
+          { "AFD Code", "st2016_3.afd.code", FT_UINT8, BASE_DEC,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_afd_ar,
+          { "Coded Frame Aspect Ratio", "st2016_3.afd.ar", FT_BOOLEAN, 8,
+            TFS(&tfs_afd_ar), 0x04, NULL, HFILL } },
+        { &hf_afd_reserved,
+          { "Reserved", "st2016_3.afd.reserved", FT_UINT8, BASE_HEX,
+            NULL, 0x83, NULL, HFILL } },
+        { &hf_reserved_1,
+          { "Reserved UDW 2", "st2016_3.reserved1", FT_UINT8, BASE_HEX,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_reserved_2,
+          { "Reserved UDW 3", "st2016_3.reserved2", FT_UINT8, BASE_HEX,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_bar_flags,
+          { "Bar Data Flags", "st2016_3.bar.flags", FT_UINT8, BASE_HEX,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_bar_top,
+          { "Top Bar Present", "st2016_3.bar.top", FT_BOOLEAN, 8,
+            NULL, 0x80, NULL, HFILL } },
+        { &hf_bar_bottom,
+          { "Bottom Bar Present", "st2016_3.bar.bottom", FT_BOOLEAN, 8,
+            NULL, 0x40, NULL, HFILL } },
+        { &hf_bar_left,
+          { "Left Bar Present", "st2016_3.bar.left", FT_BOOLEAN, 8,
+            NULL, 0x20, NULL, HFILL } },
+        { &hf_bar_right,
+          { "Right Bar Present", "st2016_3.bar.right", FT_BOOLEAN, 8,
+            NULL, 0x10, NULL, HFILL } },
+        { &hf_bar_reserved,
+          { "Reserved", "st2016_3.bar.reserved", FT_UINT8, BASE_HEX,
+            NULL, 0x0f, NULL, HFILL } },
+        { &hf_bar_value_1,
+          { "Bar Data Value 1", "st2016_3.bar.value1", FT_UINT16, BASE_HEX,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_bar_value_1_marker,
+          { "Marker Bits", "st2016_3.bar.value1.marker", FT_UINT16, BASE_HEX,
+            NULL, 0xc000, NULL, HFILL } },
+        { &hf_bar_value_1_data,
+          { "Line/Pixel Number", "st2016_3.bar.value1.data", FT_UINT16, BASE_DEC,
+            NULL, 0x3fff, NULL, HFILL } },
+        { &hf_bar_value_2,
+          { "Bar Data Value 2", "st2016_3.bar.value2", FT_UINT16, BASE_HEX,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_bar_value_2_marker,
+          { "Marker Bits", "st2016_3.bar.value2.marker", FT_UINT16, BASE_HEX,
+            NULL, 0xc000, NULL, HFILL } },
+        { &hf_bar_value_2_data,
+          { "Line/Pixel Number", "st2016_3.bar.value2.data", FT_UINT16, BASE_DEC,
+            NULL, 0x3fff, NULL, HFILL } },
+        { &hf_bar_value_1_meaning,
+          { "Meaning", "st2016_3.bar.value1.meaning", FT_STRING, BASE_NONE,
+            NULL, 0x0, NULL, HFILL } },
+        { &hf_bar_value_2_meaning,
+          { "Meaning", "st2016_3.bar.value2.meaning", FT_STRING, BASE_NONE,
+            NULL, 0x0, NULL, HFILL } },
+    };
+
+    static int *ett[] = {
+        &ett_st2016_3,
+        &ett_afd,
+        &ett_bar_flags,
+        &ett_bar_value_1,
+        &ett_bar_value_2,
+    };
+
+    static ei_register_info ei[] = {
+        { &ei_bad_length,
+          { "st2016_3.length.bad", PI_MALFORMED, PI_WARN,
+            "ST 2016-3 payload length is not 8 bytes", EXPFILL } },
+        { &ei_afd_reserved,
+          { "st2016_3.afd.reserved.bad", PI_PROTOCOL, PI_WARN,
+            "Reserved AFD bits are not zero", EXPFILL } },
+        { &ei_reserved_udw,
+          { "st2016_3.reserved_udw.bad", PI_PROTOCOL, PI_WARN,
+            "Reserved ST 2016-3 UDW is not zero", EXPFILL } },
+        { &ei_bar_reserved,
+          { "st2016_3.bar.reserved.bad", PI_PROTOCOL, PI_WARN,
+            "Reserved Bar Data flag bits are not zero", EXPFILL } },
+        { &ei_bar_flags_invalid,
+          { "st2016_3.bar.flags.invalid", PI_PROTOCOL, PI_WARN,
+            "Invalid Bar Data flag combination", EXPFILL } },
+        { &ei_bar_marker,
+          { "st2016_3.bar.marker.bad", PI_PROTOCOL, PI_WARN,
+            "Bar Data value marker bits are not binary '11'", EXPFILL } },
+    };
+
+    expert_module_t *expert_st2016_3;
+
+    proto_st2016_3 = proto_register_protocol(
+        "SMPTE ST 2016-3 AFD and Bar Data", "ST 2016-3", "st2016_3");
+
+    proto_register_field_array(proto_st2016_3, hf, array_length(hf));
+    proto_register_subtree_array(ett, array_length(ett));
+
+    expert_st2016_3 = expert_register_protocol(proto_st2016_3);
+    expert_register_field_array(expert_st2016_3, ei, array_length(ei));
+
+    st2016_3_handle =
+        register_dissector("st2016_3", dissect_st2016_3, proto_st2016_3);
+}
+
+void
+proto_reg_handoff_st2016_3(void)
+{
+    dissector_add_uint("st291.did_sdid", 0x4105, st2016_3_handle);
+}
