+static uint32_t
+get_bits_buf(const uint8_t *buf, unsigned bit_off, unsigned nbits)
+{
+    uint32_t out = 0;
+    unsigned i;
+
+    for (i = 0; i < nbits; i++) {
+        unsigned absolute = bit_off + i;
+        unsigned bit_in_byte = absolute % 8;
+        out = (out << 1) | ((buf[absolute / 8] >> (7 - bit_in_byte)) & 1U);
+    }
+    return out;
+}
