+static void
+add_generated_uint(proto_tree *tree, int hf, tvbuff_t *tvb, uint32_t value)
+{
+    proto_item *ti = proto_tree_add_uint(tree, hf, tvb, 0, 0, value);
+    proto_item_set_generated(ti);
+}
