+/* ETSI EN 301 775, Sec. 4.5.2 carries a 42-byte Teletext data block;
+ * packet addressing, page/control bits and character data follow Rec. ITU-R BT.653-3 System B. */
+static void
+process_wst_packet(tvbuff_t *tvb, proto_tree *tree)
+{
+    uint8_t bytes[42];
+    uint8_t text_data[40];
+    char data_string[41];
+    unsigned magazine, packet_number;
+    unsigned data_start_offset = 0, number_of_data_bytes = 0;
+    proto_item *ti;
+    unsigned i;
+
+    if (tvb_captured_length(tvb) < 42)
+        return;
+
+    tvb_memcpy(tvb, bytes, 0, 42);
+
+    proto_tree_add_item(tree, hf_magazine_hamming, tvb, 0, 2, ENC_BIG_ENDIAN);
+    magazine = get_bits_buf(bytes, 1, 1)
+             + 2 * get_bits_buf(bytes, 3, 1)
+             + 4 * get_bits_buf(bytes, 5, 1);
+    if (magazine == 0)
+        magazine = 8;
+    add_generated_uint(tree, hf_magazine, tvb, magazine);
+
+    proto_tree_add_item(tree, hf_packet_number_hamming, tvb, 0, 2, ENC_BIG_ENDIAN);
+    packet_number = get_bits_buf(bytes, 7, 1)
+                  + 2 * get_bits_buf(bytes, 9, 1)
+                  + 4 * get_bits_buf(bytes, 11, 1)
+                  + 8 * get_bits_buf(bytes, 13, 1)
+                  + 16 * get_bits_buf(bytes, 15, 1);
+    add_generated_uint(tree, hf_packet_number, tvb, packet_number);
+
+    if (packet_number == 0) {
+        unsigned page_units, page_tens, tt_page;
+
+        data_start_offset = 10;
+        number_of_data_bytes = 32;
+        page_units = get_bits_buf(bytes + 2, 1, 1)
+                   + 2 * get_bits_buf(bytes + 2, 3, 1)
+                   + 4 * get_bits_buf(bytes + 2, 5, 1)
+                   + 8 * get_bits_buf(bytes + 2, 7, 1);
+        page_tens = get_bits_buf(bytes + 3, 1, 1)
+                  + 2 * get_bits_buf(bytes + 3, 3, 1)
+                  + 4 * get_bits_buf(bytes + 3, 5, 1)
+                  + 8 * get_bits_buf(bytes + 3, 7, 1);
+
+        proto_tree_add_item(tree, hf_page_units_hamming, tvb, 2, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_page_tens_hamming, tvb, 3, 1, ENC_BIG_ENDIAN);
+        add_generated_uint(tree, hf_page_units, tvb, page_units);
+        add_generated_uint(tree, hf_page_tens, tvb, page_tens);
+
+        tt_page = (magazine << 8) | (page_tens << 4) | page_units;
+        proto_tree_add_none_format(tree, hf_tt_control, tvb, 0, 0,
+                                   "Control bits for TT Page 0x%x:", tt_page);
+
+        proto_tree_add_item(tree, hf_erase_page, tvb, 5, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_newsflash, tvb, 7, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_subtitle, tvb, 7, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_suppress_header, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_update_indicator, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_interrupted_sequence, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_inhibit_display, tvb, 8, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_magazine_serial, tvb, 9, 1, ENC_BIG_ENDIAN);
+        proto_tree_add_item(tree, hf_character_set, tvb, 9, 1, ENC_BIG_ENDIAN);
+    } else if (packet_number >= 1 && packet_number <= 25) {
+        data_start_offset = 2;
+        number_of_data_bytes = 40;
+    }
+
+    if (number_of_data_bytes == 0)
+        return;
+
+    for (i = 0; i < number_of_data_bytes; i++) {
+        uint8_t c = (uint8_t)get_bits_buf(bytes + data_start_offset + i, 0, 7);
+        text_data[i] = c;
+        data_string[i] = (char)c;
+    }
+    data_string[number_of_data_bytes] = '\0';
+
+    ti = proto_tree_add_string(tree, hf_data_string, tvb, 0, 0, data_string);
+    proto_item_set_generated(ti);
+    ti = proto_tree_add_bytes(tree, hf_textdata_array, tvb, 0, 0, text_data);
+    proto_item_set_generated(ti);
+}
