+/* Wireshark/Lua TvbRange:bitfield() numbers bits MSB-first. */
+static uint32_t
+get_bits_tvb(tvbuff_t *tvb, unsigned byte_off, unsigned bit_off, unsigned nbits)
+{
+    uint32_t out = 0;
+    unsigned i;
+
+    for (i = 0; i < nbits; i++) {
+        unsigned absolute = bit_off + i;
+        uint8_t b = tvb_get_uint8(tvb, byte_off + absolute / 8);
+        unsigned bit_in_byte = absolute % 8;
+        out = (out << 1) | ((b >> (7 - bit_in_byte)) & 1U);
+    }
+    return out;
+}
+
+
+static bool
+st291_id_word_parity_ok(uint16_t word)
+{
+    unsigned ones = 0;
+    unsigned i;
+    uint8_t data = (uint8_t)(word & 0xff);
+    unsigned b8 = (word >> 8) & 1U;
+    unsigned b9 = (word >> 9) & 1U;
+
+    for (i = 0; i < 8; i++)
+        ones += (data >> i) & 1U;
+
+    return (((ones + b8) & 1U) == 0) && (b9 == (b8 ^ 1U));
+}
+
+static uint8_t
+st291_word_data8(uint16_t word)
+{
+    return (uint8_t)(word & 0xff);
+}
